async fn compress(path: PathBuf) -> anyhow::Result<Vec<u8>> {
    tokio::task::spawn_blocking(move || {
        // CPU/disk-bound work on the blocking pool; brief backoff on EBUSY
        std::thread::sleep(std::time::Duration::from_millis(50));
        zstd::encode_all(std::fs::File::open(path)?, 19)
    })
    .await?
    .map_err(Into::into)
}
